import{I as p,o as h,c as m,j as s,a as t,J as a,w as l,b6 as i,cN as b,cO as _,cP as q,cQ as I,cR as k,cS as A,cT as f,cU as x,cV as v,cW as y,cX as C,cY as T,cZ as E,c_ as P,c$ as D,d0 as S,d1 as V,d2 as N,d3 as R,k as w}from"./chunks/framework.BUXTSoD9.js";import{r as O}from"./chunks/relatedArticles.DIHQAH-1.js";const B={style:{margin:"50px 0"}},j={style:{margin:"50px 0"}},G={style:{margin:"50px 0"}},W={style:{margin:"50px 0"}},K=JSON.parse('{"title":"صنع النموذج الأولي - من تحليل الأعمال إلى تنفيذ نموذج منتج متعدد الصفحات","description":"تجربة الدورة الكاملة من تحليل الأعمال إلى تنفيذ نموذج منتج متعدد الصفحات. تعلم كيف تطرح أسئلة الأعمال وتحلل المتطلبات وتستخدم AI IDE لتوليد تطبيقات صفحة واحدة ومتعددة الصفحات مع تحسين واختبار النموذج الأولي.","frontmatter":{"title":"صنع النموذج الأولي - من تحليل الأعمال إلى تنفيذ نموذج منتج متعدد الصفحات","description":"تجربة الدورة الكاملة من تحليل الأعمال إلى تنفيذ نموذج منتج متعدد الصفحات. تعلم كيف تطرح أسئلة الأعمال وتحلل المتطلبات وتستخدم AI IDE لتوليد تطبيقات صفحة واحدة ومتعددة الصفحات مع تحسين واختبار النموذج الأولي."},"headers":[],"relativePath":"ar-sa/stage-1/building-prototype/index.md","filePath":"ar-sa/stage-1/building-prototype/index.md"}'),z={name:"ar-sa/stage-1/building-prototype/index.md"},Q=Object.assign(z,{setup(F){const g="حوالي <strong>8 ساعات</strong>",u=O["ar-sa/stage-1/building-prototype"]??[];return(J,n)=>{const c=p("ChapterIntroduction"),o=p("StepBar"),r=p("ClientOnly"),e=p("el-card"),d=p("RelatedArticlesSection");return h(),m("div",null,[n[5]||(n[5]=s("h1",{id:"المستوى-الثالث-صنع-النموذج-الأولي-عمليًا",tabindex:"-1"},[t("المستوى الثالث: صنع النموذج الأولي عمليًا "),s("a",{class:"header-anchor",href:"#المستوى-الثالث-صنع-النموذج-الأولي-عمليًا","aria-label":"Permalink to “المستوى الثالث: صنع النموذج الأولي عمليًا”"},"​")],-1)),n[6]||(n[6]=s("h2",{id:"دليل-هذا-الفصل",tabindex:"-1"},[t("دليل هذا الفصل "),s("a",{class:"header-anchor",href:"#دليل-هذا-الفصل","aria-label":"Permalink to “دليل هذا الفصل”"},"​")],-1)),a(c,{duration:g,tags:["تحليل الأعمال","تصميم النماذج الأولية","البرمجة بمساعدة AI","تطبيقات متعددة الصفحات"],coreOutput:"نموذج أولي لمنصة مواد التجارة الإلكترونية",expectedOutput:"نموذج ويب تفاعلي"},{default:l(()=>[...n[0]||(n[0]=[s("p",null,[t("في الفصل السابق، تعلمنا كيفية "),s("strong",null,"إيجاد أفكار جيدة"),t(" — انطلاقًا من احتياجات المستخدمين، للعثور على اتجاه يرغب الناس في الدفع مقابل него. لكن إيجاد الاتجاه هو مجرد الخطوة الأولى، "),s("strong",null,"التحدي الحقيقي لمدير المنتج هو: كيف تحول المتطلبات الغامضة إلى منتج قابل للاستخدام.")],-1),s("p",null,[t("في هذا الفصل، سنحل "),s("strong",null,"مشكلة واقعية"),t(': يلقي المدير عليك عبارة "استخدم AI لتحسين كفاءة نشر المنتجات على منصة التجارة الإلكترونية" — كيف تحولها إلى '),s("strong",null,"نموذج أولي لمنتج قابل للاستخدام؟")],-1),s("p",null,[t("على عكس صنع لعبة الثعبان أو الآلة الحاسبة، "),s("strong",null,"الأعمال الحقيقية لا يمكن بناؤها بالخيال"),t(":")],-1),s("ol",null,[s("li",null,[s("strong",null,"تحديد نقطة الألم"),t(": تحدث مع فريق التشغيل، واستخرج "),s("strong",null,"نقطة الألم الحقيقية"),t(' من عبارة "تحسين الكفاءة" الغامضة')]),s("li",null,[s("strong",null,"ركز على الأهم"),t(": من بين مجموعة من المشاكل، حل "),s("strong",null,"الأكثر إيلامًا أولًا"),t("، لا تفكر في حل كل شيء دفعة واحدة")]),s("li",null,[s("strong",null,"تحقق بسرعة"),t(": استخدم AI IDE لصنع "),s("strong",null,"نموذج أولي لصفحة واحدة"),t(" أولًا، ثم وسّعه إلى تطبيق متعدد الصفحات")]),s("li",null,[s("strong",null,"اصنع شيئًا قابلًا للاستخدام"),t(": سلم أخيرًا "),s("strong",null,"منصة مواد تجارة إلكترونية يمكن عرضها وتشغيلها")])],-1),s("p",null,[t("سننتقل من "),s("strong",null,"صنع الألعاب إلى صنع التطبيقات"),t("، ونتعلم "),s("strong",null,"التعاطف والتفكير في الاحتياجات الحقيقية للعملاء"),t(".")],-1)])]),_:1}),n[7]||(n[7]=s("div",{class:"info custom-block"},[s("p",{class:"custom-block-title"},"ℹ️ ملاحظة"),s("p",null,"قد تحتوي هذه المقالة على بعض المصطلحات التجارية، إذا لم تفهمها يمكنك سؤال AI للحصول على شرح.")],-1)),s("div",B,[a(r,null,{default:l(()=>[a(o,{active:0,items:[{title:"تحليل المتطلبات",description:"من الغامض إلى المحدد"},{title:"التحقق من صفحة واحدة",description:"تنفيذ الوظيفة الأساسية"},{title:"التوسع متعدد الصفحات",description:"تحسين بنية التطبيق"},{title:"التحسين والتجميل",description:"تحسين تجربة المستخدم"}]})]),_:1})]),n[8]||(n[8]=i('<h2 id="_1-تحديد-المتطلبات-قبل-كتابة-الكود" tabindex="-1">1. تحديد المتطلبات قبل كتابة الكود <a class="header-anchor" href="#_1-تحديد-المتطلبات-قبل-كتابة-الكود" aria-label="Permalink to “1. تحديد المتطلبات قبل كتابة الكود”">​</a></h2><p>في البرامج التعليمية السابقة، استخدمنا AI IDE لتوليد لعبة الثعبان وألعاب صغيرة متنوعة بسهولة، لكن هذه تُعد مجرد مشاريع ألعاب ولا يمكن تطبيقها في العمل والحياة؛ إذا أردنا أن تكون قدرات AI مفيدة حقًا للجميع، فيجب أن نجمع بين سيناريوهات الحياة والعمل في البرمجة بنمط vibe coding.</p><p>في الفصل السابق تعلمنا كيفية إيجاد <strong>أفكار جيدة يرغب الناس في الدفع مقابلها</strong>، لكن إيجاد الاتجاه هو مجرد البداية. عند صنع منتج حقيقي، ستكتشف: <strong>هناك فجوة هائلة بين معرفة &quot;ماذا نصنع&quot; ومعرفة &quot;كيف نصنع&quot;.</strong></p><p>هذه الفجوة هي <strong>تحديد المتطلبات بشكل ملموس</strong>.</p><p>على سبيل المثال، في المشاريع الصفية أو الشخصية، نبدأ غالبًا من أبسط وظيفة قابلة للتنفيذ لصنع المنتجات والتطبيقات:</p><ul><li>&quot;اصنع لوحة Kanban، ضع المهام فيها.&quot;</li><li>&quot;ساعدني في صنع أداة رسم.&quot;</li><li>&quot;ساعدني في صنع برنامج لجمع الاستبيانات.&quot;</li></ul><p>غالبًا ما تكون هذه مجرد أداة أو وحدة وظيفية واحدة، بل لا يمكن حتى اعتبارها مشكلة عمل واضحة. الأهم من ذلك، <strong>هذه الأفكار غالبًا ما تكون &quot;أنت تعتقد أنها مفيدة&quot; وليست &quot;المستخدم يحتاجها حقًا&quot;.</strong></p><p>في المشاريع على مستوى المؤسسات أو المشاريع الناشئة، غالبًا ما ينطلق مديرو المنتجات والمهندسون من مسألة أعمال أكبر. على سبيل المثال، يمكننا افتراض السيناريو التالي:</p>',8)),a(e,{shadow:"hover",style:{"border-left":"5px solid #409EFF","background-color":"#ecf5ff",margin:"20px 0"}},{default:l(()=>[...n[1]||(n[1]=[s("div",{style:{"font-weight":"bold",color:"#303133","margin-bottom":"10px"}},"🛍️ سيناريو الأعمال:",-1),s("div",{style:{color:"#606266","line-height":"1.6"}},[s("p",null,"أنت مدير منتج التجارة الإلكترونية لمتجر. أعطاك المدير مسألة غامضة لكنها تمثل ضغطًا كبيرًا:"),s("p",{style:{"font-style":"italic","margin-top":"10px"}},'"الجميع يستخدمون AI الآن لصنع الصور وكتابة النصوص، ويبدو الأمر بسيطًا جدًا. ساعدني في ذلك لجعل نشر المنتجات الجديدة على منصة التجارة الإلكترونية أكثر كفاءة."')],-1)])]),_:1}),n[9]||(n[9]=i(`<p>في هذه اللحظة قد تفكر: &quot;المدير يحلم مرة أخرى!&quot;، ومع ذلك، في العمل الفعلي هذه الظاهرة المتمثلة في اتخاذ القرار بعبارة غامضة شائعة جدًا، بل أكثر تكرارًا من طلبك للشاي بالحليب أسبوعيًا. لذلك، لتكون موظفًا مؤهلاً (أو CEO لشركة ناشئة)، يجب أن نتعلم كيفية الانتقال من صنع الأدوات الشخصية إلى صنع نماذج أولية لمنتجات حقيقية.</p><p>بما أننا تعلمنا استخدام AI IDE، إذا فكرت مليًا، هذا المطلب بسيط جدًا في الواقع، أليس كذلك؟ فقط أعطِ AI prompt بناءً على هذا، وارمه لـ Agent وستنتهي المشكلة!</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>يرجى الرجوع إلى متطلباتي xxxx،</span></span>
<span class="line"><span>وساعدني في تصميم منصة مواد التجارة الإلكترونية،</span></span>
<span class="line"><span>تتضمن وظائف إنشاء وإدارة مواد مثل أوصاف المنتجات والصور ومقاطع الفيديو.</span></span></code></pre></div><p>إذا حمست وأرسلت هذا المطلب مباشرة كنموذج أولي للمدير — تهانينا، مكافأة هذا الربع ستُلغى!</p><p><strong>لماذا يحدث هذا؟ هذا هو الألم الأساسي الذي يجب علينا حله:</strong></p><p>عندما تعلمنا استخدام AI IDE سابقًا، كنا نصنع <strong>مشاريع ألعاب نستخدمها نحن</strong> مثل لعبة الثعبان والآلة الحاسبة — وظائف بسيطة، نعرف ما نريده، ونستخدمها بأنفسنا. لكن <strong>سيناريوهات الأعمال الحقيقية مختلفة تمامًا</strong>:</p><ul><li><strong>أنت لست المستخدم</strong>: المدير يريد &quot;تحسين الكفاءة&quot;، لكنك لا تعرف كيف يعمل فريق التشغيل يوميًا وأين يواجهون العقبات؛</li><li><strong>AI لا يفهم الأعمال أيضًا</strong>: إذا أعطيت AI مطلبًا غامضًا، سيخمن بناءً على معرفته العامة، والنتيجة قد تبدو جيدة لكنها غير قابلة للاستخدام عمليًا؛</li><li><strong>الفكرة الجيدة لا تساوي منتجًا جيدًا</strong>: قد تعتقد أن &quot;إضافة وظيفة إنشاء AI&quot; رائعة، لكن المستخدم قد لا يحتاجها أصلًا، أو قد يكون استخدامها أكثر إزعاجًا من الطريقة السابقة.</li></ul><p><strong>لهذا السبب يجب أن نتعلم &quot;من الفكرة إلى فهم المستخدم&quot;</strong> فقط عندما يحل إبداعك مشكلة شخص آخر حقًا، وتطرح أسئلة وتفهم الأعمال بعمق، يمكنك صنع أشياء ذات قيمة حقيقية. (الفكرة الجيدة حتى أكثر أهمية من التقنية الجيدة)</p><h3 id="_1-1-من-الخيال-إلى-الواقع-تعلم-كيف-تطرح-أسئلة-الأعمال" tabindex="-1">1.1 من الخيال إلى الواقع: تعلم كيف تطرح أسئلة الأعمال <a class="header-anchor" href="#_1-1-من-الخيال-إلى-الواقع-تعلم-كيف-تطرح-أسئلة-الأعمال" aria-label="Permalink to “1.1 من الخيال إلى الواقع: تعلم كيف تطرح أسئلة الأعمال”">​</a></h3><div class="info custom-block"><p class="custom-block-title">💡 أولًا: ما هي المتطلبات؟ ما هي الأعمال؟</p><p><strong>المتطلبات</strong> هي ما يريده المستخدم حقًا، هي المشاكل التي يواجهها ويريد حلها. مثل &quot;يريد المدير أن أجعل نشر المنتجات أسرع&quot;، هذا مطلب.</p><p><strong>الأعمال</strong> هي ما يفعله المستخدم فعليًا كل يوم، طريقة عملهم. مثل ما يفعله فريق تشغيل التجارة الإلكترونية يوميًا: نشر المنتجات، تغيير الأسعار، صنع الصور، عرض البيانات... هذه كلها أعمال.</p><p><strong>لماذا نهتم بالأعمال؟</strong> لأنك إذا لم تفهم الأعمال، فالأداة التي تصنعها قد تكون &quot;تبدو جيدة لكن لا أحد يستخدمها&quot;. فقط عندما تفهم حقًا كيف يعمل المستخدم يوميًا وأين يواجه العقبات، يمكنك صنع ما يساعدهم حقًا.</p></div><p>من أبسط منظور، يمكنك أن تسأل نفسك أولاً بضعة أسئلة:</p><ul><li>عندما يقول المدير &quot;<strong>كفاءة أعلى</strong>&quot;، ماذا يعني تحديدًا؟ هل يعني <strong>العمل بشكل أسرع</strong>؟ أم <strong>إنفاق أقل</strong>؟ أم <strong>بيع المزيد</strong>؟</li><li>كيف يتم نشر المنتجات حاليًا؟ <strong>أين توجد العقبات</strong>؟</li><li>كم <strong>منتج جديد</strong> يُنشر يوميًا؟ لكل منتج كم <strong>صورة</strong> يجب صنعها وكم <strong>كلمة</strong> يجب كتابتها؟</li><li>في العمل الحالي، <strong>أي شيء هو الأكثر إزعاجًا</strong> و<strong>أقل ما تريد فعله</strong>؟</li></ul><p>لكن هذه كلها أسئلة تخمينية، يجب أن نسأل فريق أعمال التجارة الإلكترونية مباشرة، &quot;أين تكمن صعوباتكم واهتماماتكم؟&quot;، للحصول على إجابات أكثر دقة من خلال التواصل:</p><div class="info custom-block"><p class="custom-block-title">📋 نتائج مقابلة الأعمال الحقيقية</p><p>سألنا أشخاصًا يعملون في تشغيل التجارة الإلكترونية، وقالوا هذه الشكاوى:</p><p><strong>1. أشياء كثيرة جدًا ومتنوعة</strong></p><ul><li>شخص واحد يدير عدة متاجر، لكل متجر العديد من المنتجات التي يجب التعامل معها؛</li><li>مشغول طوال اليوم: <strong>نشر منتجات جديدة</strong>، <strong>تغيير الأسعار</strong>، <strong>صنع الصور</strong>، <strong>عرض البيانات</strong>، شيء لم ينتهِ قبل أن يبدأ شيء آخر.</li></ul><p><strong>2. صنع المحتوى ليس مرة واحدة بل تجربة وتكرار</strong></p><ul><li>ابدأ أولاً باستخدام <strong>الصور من المصنع</strong> أو <strong>المواد المستخدمة سابقًا</strong> أو <strong>الصور المرجعية من الإنترنت</strong>، ونشر المنتجات بسرعة <strong>للتجربة</strong>؛</li><li>أنفق مبلغًا صغيرًا على الترويج، <strong>شاهد هل هناك من يشتري</strong>؛</li><li>فقط <strong>المنتجات التي تباع جيدًا</strong>، سيتم بذل الجهد في صنع صورها وكتابة تفاصيلها وتصوير مقاطع فيديو لها.</li></ul></div><p>بعد مقابلة فريق الأعمال، نحن متحمسون، لأننا الآن قادرون حقًا على صنع نموذج أولي مثالي يتناسب مع الأعمال! — خطأ مرة أخرى، إذا حاولنا &quot;إرضاء جميع المطالب دفعة واحدة&quot;، سيكون المنتج ضخمًا جدًا ومن الصعب تنفيذه في وقت الدورة. لذلك، نحتاج إلى مزيد من التنظيم والتضييق للعثور على نقطة الألم الأساسية الحقيقية.</p><h3 id="_1-2-من-التوسع-إلى-التضييق-تحديد-نقطة-الألم-الأساسية-والوظائف" tabindex="-1">1.2 من التوسع إلى التضييق: تحديد نقطة الألم الأساسية والوظائف <a class="header-anchor" href="#_1-2-من-التوسع-إلى-التضييق-تحديد-نقطة-الألم-الأساسية-والوظائف" aria-label="Permalink to “1.2 من التوسع إلى التضييق: تحديد نقطة الألم الأساسية والوظائف”">​</a></h3><div class="info custom-block"><p class="custom-block-title">💡 لماذا &quot;التضييق&quot;؟ ما هي &quot;نقطة الألم&quot;؟</p><p><strong>المشاكل كثيرة، لكن أيها نبدأ بها أولًا؟</strong> قد يخبرك المستخدم بحزمة من المشاكل: A مزعج، B مزعج، C مزعج... لكن إذا حاولت حل جميع المشاكل دفعة واحدة، قد لا تحل أيًا منها بشكل جيد. لذلك يجب <strong>التضييق</strong> — أي اختيار <strong>الأكثر إيلامًا والأكثر إلحاحًا والأكثر قابلية للحل</strong> من بين مجموعة من المشاكل للبدء به.</p><p><strong>ما هي نقطة الألم؟</strong> هي المشكلة المحددة التي <strong>يزعجها المستخدم أكثر وتستهلك وقته أكثر ويريد حلها بشدة</strong>. ليست &quot;أعتقد أنها مفيدة&quot;، بل شيء <strong>يشتكو منه المستخدم يوميًا ويتألم في كل مرة يفعله</strong>.</p></div><p>من خلال المقابلة أعلاه، اكتشفنا أن فريق التشغيل يواجه العديد من المشاكل: انقطاع الإيقاع بسبب الأنشطة، إدارة متاجر متعددة، التنقل بين النشر/تغيير الأسعار/صنع الصور/عرض البيانات...</p><p>إذا حاولنا &quot;حل جميع هذه المشاكل&quot;، سنصنع أداة <strong>ضخمة وشاملة لكنها غير سهلة الاستخدام</strong>.</p><p>دعنا نصنف هذه المشاكل (يمكنك طلب المساعدة من AI)، هناك تقريبًا ثلاث فئات:</p><ol><li><strong>مشاكل الإيقاع</strong>: متى يتم النشر، متى يتم تعديل الأسعار؛</li><li><strong>مشاكل الكفاءة</strong>: كيفية إدارة متاجر ومنتجات متعددة في نفس الوقت؛</li><li><strong>مشاكل المحتوى</strong>: كيفية صنع صور ومنتجات تجارية بسرعة.</li></ol><p>بالنسبة لدورتنا، الأنسب للبدء به هو <strong>الفئة الثالثة: مشاكل صنع المحتوى</strong>. لكن &quot;صنع المحتوى بسرعة&quot; لا يزال تجريديًا بعض الشيء، دعنا نسأل فريق الأعمال عن العقبات المحددة:</p><div class="info custom-block"><p class="custom-block-title">📋 فريق الأعمال يقول: هناك مكانان مؤلمان في صنع المحتوى</p><p><strong>الألم 1: صنع الصور والنصوص بشكل جماعي مرهق جدًا</strong></p><ul><li>المواد متناثرة في كل مكان: القرص السحابي، سجلات WeChat، منصة الخلفية... <strong>العثور عليها صعب</strong>؛</li><li>يجب نشر العديد من المنتجات مرة واحدة، <strong>لا يوجد وقت للإتقان واحدًا تلو الآخر</strong>، فقط تُركب بسرعة؛</li><li>المتطلبات ليست عالية، <strong>يكفي أن تكون قابلة للعرض والنشر</strong>، لا تحتاج إلى أن تكون جميلة.</li></ul><p><strong>الألم 2: الحلول الجيدة لا يمكن حفظها لإعادة الاستخدام</strong></p><ul><li>العناوين والتخطيطات الجيدة التي تم صنعها سابقًا، <strong>عندما نريد استخدامها مرة أخرى لا نجدها</strong>؛</li><li>الحلول متناثرة في سجلات المحادثة وروابط المنتجات السابقة؛</li><li>عند الحاجة لاستخدامها يجب <strong>البحث طويلاً ونسخ ولصق وتعديل لفترة طويلة</strong>؛</li><li>ينقص أداة يمكن <strong>الحفظ والإدارة والتطبيق المباشر</strong>.</li></ul></div><p>بناءً على نقطتي الألم هاتين، سنصنع أداة بسيطة: <strong>مساعدة فريق التشغيل في صنع الصور والنصوص بشكل جماعي، وحفظ الحلول الجيدة للاستخدام المباشر في المرة القادمة</strong>.</p><p>ستقوم بفعلين فقط (يمكنك طلب المساعدة من AI للتفصيل، وتذكر حذف الوظائف بناءً على ملاحظات الأعمال باستمرار):</p><div class="info custom-block"><p class="custom-block-title">الوظيفة 1: إنشاء صور ومنتجات التجارة الإلكترونية بشكل جماعي</p><p><strong>ماذا تفعل؟</strong> إعطاء النظام بعض معلومات المنتج، وسيقوم تلقائيًا بإنشاء صور المنتج والنصوص القابلة للنشر على منصات التجارة الإلكترونية (مثل Douyin و Taobao).</p><p><strong>المدخلات</strong></p><table tabindex="0"><thead><tr><th>النوع</th><th>المحتوى</th></tr></thead><tbody><tr><td>معلومات المنتج</td><td>الاسم، الفئة، العلامة التجارية، المادة، الحجم، اللون، إلخ</td></tr><tr><td>صور المنتج</td><td>صور بخلفية بيضاء أو صور مشاهد بسيطة</td></tr><tr><td>صور مرجعية</td><td>لقطات شاشة لمنتجات بيعت جيدًا سابقًا أو روابط مرجعية</td></tr><tr><td>طريقة الاستيراد</td><td>استيراد جماعي عبر Excel، أو ملء مباشر على الصفحة</td></tr></tbody></table><p><strong>المخرجات (مواد التجارة الإلكترونية المولدة)</strong></p><ul><li><strong>الصورة الرئيسية للمنتج</strong>: صورة عرض المنتج مع نقاط بيع نصية (الصورة الأولى التي يراها المستخدم عند التصفح)</li><li><strong>عنوان المنتج</strong>: مجموعة كلمات مفتاحية يمكن البحث عنها</li><li><strong>نص نقاط البيع</strong>: 1-2 جملة جذابة للمشترين</li><li>كلها <strong>منتجات جاهزة يمكن تعديلها قليلاً ونشرها</strong></li></ul><p><strong>التأثير</strong></p><ul><li>سابقًا: كل منتج يجب البدء من الصفر لصنع الصور وكتابة النصوص</li><li>الآن: رمي مجموعة من المنتجات في النظام، وبعد التوليد اختر وعدّل</li></ul></div><div class="info custom-block"><p class="custom-block-title">الوظيفة 2: حفظ الحلول الجيدة كقوالب</p><p><strong>المدخلات</strong></p><table tabindex="0"><thead><tr><th>النوع</th><th>المحتوى</th></tr></thead><tbody><tr><td>مجموعة كاملة</td><td>الصورة الرئيسية + العنوان + النص</td></tr></tbody></table><p><strong>المخرجات</strong></p><table tabindex="0"><thead><tr><th>الوظيفة</th><th>الوصف</th></tr></thead><tbody><tr><td>التطبيق</td><td>عند صنع منتجات جديدة، استخدم القالب للتوليد التلقائي</td></tr><tr><td>التعديل</td><td>تعديل العنوان والنص مباشرة</td></tr><tr><td>الإدارة</td><td>إعطاء اسم وإضافة علامات (مثل &quot;قالب حقائب رجالية&quot; &quot;عنوان ترويج كبير&quot;)، للسهولة في البحث</td></tr></tbody></table><p><strong>التأثير</strong></p><ol><li>استيراد منتجات جديدة</li><li>الاختيار: ترك النظام يولد افتراضيًا، أو <strong>استخدام القالب الذي حفظته</strong></li><li>النظام يطبق نمط القالب تلقائيًا ويخرج صور ونصوص جديدة</li></ol></div><hr><p><strong>مراجعة ما فعلناه للتو:</strong></p><ol><li><strong>اسأل أولًا</strong>: لا تبدأ بالعمل مباشرة، بل اسأل فريق التشغيل &quot;ما الذي يزعجكم أكثر&quot;؛</li><li><strong>اعثر على نقطة الألم</strong>: اكتشفنا أن أكثر ما يؤلمهم هو &quot;صنع الصور وكتابة النصوص مرهق جدًا&quot; و&quot;الحلول الجيدة لا يمكن حفظها&quot;؛</li><li><strong>ضيق النطاق</strong>: لا نصنع منصة شاملة، بل نفعل وظيفتين فقط: &quot;إنشاء الصور والنصوص بشكل جماعي + حفظ القوالب&quot;.</li></ol><p><strong>لماذا هذا مهم؟</strong></p><p>الخطأ الشائع للمبتدئين في صنع المنتجات: كلما زادت الوظائف كان ذلك أفضل. لكن ما يحتاجه المستخدم حقًا هو <strong>حل المشكلة الأكثر إيلامًا</strong>. صنع مجموعة من الوظائف لكنها كلها غير سهلة الاستخدام، أفضل من صنع وظيفة أو اثنتين تساعد المستخدم حقًا.</p><p><strong>جوهر تفكير المنتج والأعمال:</strong></p><ul><li>لا تفكر &quot;أعتقد أن المستخدم يحتاج إلى ماذا&quot;</li><li>اذهب واسأل المستخدم &quot;ماذا تفعل كل يوم؟ أين الألم؟&quot;</li><li>من مجموعة من المشاكل <strong>ضيق</strong> إلى الأكثر إيلامًا والأكثر قابلية للحل</li><li>اصنع <strong>أصغر نسخة قابلة للاستخدام</strong> أولًا، ثم حسّن تدريجيًا</li></ul><p>هذا ما يجب التفكير فيه قبل كتابة الكود. الكود مجرد أداة، <strong>فهم المستخدم وتحديد المشكلة بدقة</strong> هو الخطوة الأولى.</p>`,35)),s("div",j,[a(r,null,{default:l(()=>[a(o,{active:1,items:[{title:"تحليل المتطلبات",description:"من الغامض إلى المحدد"},{title:"التحقق من صفحة واحدة",description:"تنفيذ الوظيفة الأساسية"},{title:"التوسع متعدد الصفحات",description:"تحسين بنية التطبيق"},{title:"التحسين والتجميل",description:"تحسين تجربة المستخدم"}]})]),_:1})]),n[10]||(n[10]=i(`<h2 id="_2-نموذج-أولي-في-10-دقائق-دع-ai-ide-ينفذ-الوظيفة-الأساسية" tabindex="-1">2. نموذج أولي في 10 دقائق: دع AI IDE ينفذ &quot;الوظيفة الأساسية&quot; <a class="header-anchor" href="#_2-نموذج-أولي-في-10-دقائق-دع-ai-ide-ينفذ-الوظيفة-الأساسية" aria-label="Permalink to “2. نموذج أولي في 10 دقائق: دع AI IDE ينفذ &quot;الوظيفة الأساسية&quot;”">​</a></h2><div class="info custom-block"><p class="custom-block-title">💡 اقتراح خطة البرمجة</p><p>إذا كنت تشعر أن IDE الحالي ليس ذكيًا بما فيه الكفاية، أو أنك استهلكت حصتك بسرعة، يمكنك شراء <strong>خطة برمجة Plan</strong>. راجع <a href="./../../stage-2/backend/modern-cli/">هذه المقالة</a> لاستخدام Claude في البرمجة.</p></div><p>التفكير جيد، لكن لا تفرط في التفكير، دعنا نتحكم في التأمل المفرط ونحاول البدء بصنع النموذج الأولي من صفحة واحدة.</p><h3 id="_2-1-الخطوة-الأولى-أخبر-ai-بما-تريده-بلغة-بسيطة" tabindex="-1">2.1 الخطوة الأولى: أخبر AI بما تريده بلغة بسيطة <a class="header-anchor" href="#_2-1-الخطوة-الأولى-أخبر-ai-بما-تريده-بلغة-بسيطة" aria-label="Permalink to “2.1 الخطوة الأولى: أخبر AI بما تريده بلغة بسيطة”">​</a></h3><p>في البداية لا تسعى للغة مثالية في prompt، ابدأ من أكثر تعبير طبيعي لديك. تمامًا مثل وصف المتطلبات لزميل العمل، أخبر AI بما تريد صنعه بلغة بسيطة، ثم دع AI يساعدك في تحسينه إلى تعبير أكثر احترافية.</p><h4 id="_2-1-1-ابدأ-بالوصف-الشفهي-موصى-به-للمبتدئين" tabindex="-1">2.1.1 ابدأ بالوصف الشفهي (موصى به للمبتدئين) <a class="header-anchor" href="#_2-1-1-ابدأ-بالوصف-الشفهي-موصى-به-للمبتدئين" aria-label="Permalink to “2.1.1 ابدأ بالوصف الشفهي (موصى به للمبتدئين)”">​</a></h4><p>صف فكرتك بكلماتك الخاصة، حتى لو كانت خشنة لا بأس:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>أريد صنع أداة تساعد فريق تشغيل التجارة الإلكترونية في إنشاء الصور الرئيسية والنصوص للمنتجات تلقائيًا.</span></span>
<span class="line"><span>فريق التشغيل يصنع الصور والنصوص يدويًا واحدًا تلو الآخر، وهذا مزعج جدًا.</span></span>
<span class="line"><span>فكرتي هي: يرفعون معلومات المنتج، والنظام يولد مجموعة من المسودات تلقائيًا،</span></span>
<span class="line"><span>وفريق التشغيل يختار الجيد وعدّل قليلاً ليكون جاهزًا للاستخدام.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ابدأ بأبسط إصدار: صفحة واحدة، على اليسار ملء معلومات المنتج،</span></span>
<span class="line"><span>على اليمين عرض النتائج المولدة. يمكن رفع الصور وملء النصوص،</span></span>
<span class="line"><span>بعد التوليد عرض معاينة الصورة الرئيسية والنصوص.</span></span></code></pre></div><p>بعد ذلك، أرسل هذه الفقرة إلى AI (مثل ChatGPT أو Claude)، واطلب منه مساعدتك في التوسيع. عادةً ما سيساعدك AI في إضافة تفاصيل لم تفكر فيها، وينظم أفكارك بشكل أوضح، وفي النهاية يولد prompt مناسبًا لإرساله إلى AI IDE.</p><p>يمكنك أن تقول لـ AI بهذه الطريقة:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ساعدني في توسيع الأفكار أعلاه، وتنظيمها في وثيقة منطق أعمال واضحة،</span></span>
<span class="line"><span>ثم ولّد prompt مناسبًا لإرساله إلى AI IDE (مثل Cursor أو Trae)،</span></span>
<span class="line"><span>لاستخدامه لتوليد كود نموذج أولي لتطبيق صفحة واحدة.</span></span></code></pre></div><p>ستُرجع AI وثيقة منظمة من المتطلبات و prompt المقابل. تحقق منها بنفسك، واحذف الوظائف غير الضرورية، وبعد التأكد من صحتها استخدمها لتوليد الكود.</p><p>فائدة هذا النهج: ما تصفه شفهيًا هو أفكارك الحقيقية، لكن قد تفوت بعض التفاصيل المهمة. عندما يساعدك AI في التوسيع، قد يسأل &quot;هل تريد دعم الرفع الجماعي؟&quot; وهو سؤال لم تفكر فيه، مما يساعدك في التحقق الإضافي. يمكنك اختيار الاحتفاظ أو حذف الوظائف غير العملية بناءً على الملاحظات، وتحديد prompt النسخة الأولى الذي تعطيه لـ AI من خلال التعديل المتكرر.</p><h4 id="_2-1-2-تخطي-مرحلة-التوسيع-أرسل-وثيقة-الأعمال-المنظمة-مباشرة-إلى-ai" tabindex="-1">2.1.2 تخطي مرحلة التوسيع: أرسل وثيقة الأعمال المنظمة مباشرة إلى AI <a class="header-anchor" href="#_2-1-2-تخطي-مرحلة-التوسيع-أرسل-وثيقة-الأعمال-المنظمة-مباشرة-إلى-ai" aria-label="Permalink to “2.1.2 تخطي مرحلة التوسيع: أرسل وثيقة الأعمال المنظمة مباشرة إلى AI”">​</a></h4><p>إذا كنت قد نظمت بالفعل وثيقة منطق الأعمال في الفصول السابقة (مثل وصف المتطلبات المكتوب بلغة بسيطة)، يمكنك استخدام التنسيق أدناه مباشرة لإرساله إلى AI IDE، متخطيًا خطوة توسيع AI. مناسب للحالات التي تكون فيها المتطلبات واضحة بالفعل وتريد البدء مباشرة في كتابة الكود:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ساعدني في تنفيذ تطبيق صفحة واحدة بناءً على منطق الأعمال للتحقق من وظائف اللعب الأساسية.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>مرجع منطق الأعمال كما يلي:</span></span>
<span class="line"><span>1. مساعدة فريق التشغيل في إنشاء المسودة الأولى للصور والنصوص بشكل جماعي:</span></span>
<span class="line"><span>- **المدخلات (دعم الرفع المباشر والاستيراد الجماعي للمواد):**</span></span>
<span class="line"><span>  - المعلومات الأساسية للمنتج: الاسم، الفئة، العلامة التجارية، المادة، الحجم، اللون، الفئة المستهدفة، إلخ؛</span></span>
<span class="line"><span>  - صور المنتج: صور بخلفية بيضاء / صور مشاهد بسيطة؛</span></span>
<span class="line"><span>  - كل توليد يدعم رفع لقطات شاشة لمنتجات ناجحة سابقًا أو روابط مرجعية إضافية؛</span></span>
<span class="line"><span>  - دعم الاستيراد الجماعي عبر Excel، أو الإدخال/الرفع عبر الإنترنت على الصفحة.</span></span>
<span class="line"><span>  - دعم تحديد ما إذا كان سيتم حفظ مواد المنتج في مكتبة المواد على الصفحة، للسهولة في الاستخدام لاحقًا</span></span>
<span class="line"><span>- **المخرجات (محتوى يمكن نشره مباشرة أو نشره بعد تعديل بسيط):**</span></span>
<span class="line"><span>  - لكل منتج مسودة صورة رئيسية &quot;مقبولة تحتوي على نقاط بيع أساسية&quot;؛</span></span>
<span class="line"><span>  - عنوان &quot;ببنية معقولة يحتوي على كلمات مفتاحية أساسية&quot; + 1-2 جملة نص نقاط بيع.</span></span>
<span class="line"><span>- **التغيير المتوقع في طريقة الاستخدام:**</span></span>
<span class="line"><span>  من البدء من الصفر لكل دفعة منتجات إلى رمي مجموعة منتجات في النظام، وأخذ المسودات المولدة للفرز والتعديل الدقيق.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ابدأ بالوظيفة الأولى، الوظيفة الثانية (مكتبة القوالب) ستُضاف لاحقًا.</span></span></code></pre></div><h4 id="_2-1-3-طريقة-المبرمج-متقدم-دع-ai-يساعدك-في-كتابة-prompt-الـ-prompt" tabindex="-1">2.1.3 طريقة المبرمج (متقدم): دع AI يساعدك في كتابة &quot;prompt الـ prompt&quot; <a class="header-anchor" href="#_2-1-3-طريقة-المبرمج-متقدم-دع-ai-يساعدك-في-كتابة-prompt-الـ-prompt" aria-label="Permalink to “2.1.3 طريقة المبرمج (متقدم): دع AI يساعدك في كتابة &quot;prompt الـ prompt&quot;”">​</a></h4><p>إذا كنت تريد تحكمًا أدق في عملية توليد الكود، يمكنك أولًا جعل AI (مثل ChatGPT) يولد prompt مخصصًا لـ AI IDE بناءً على متطلباتك:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>بناءً على الأفكار أدناه، ساعدني في كتابة prompt لـ coding Agent،</span></span>
<span class="line"><span>أحتاج إلى استخدام هذا prompt لتوليد الكود.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[الصق وصف منطق الأعمال هنا]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>المتطلبات:</span></span>
<span class="line"><span>1. يجب أن يتضمن prompt وصفًا واضحًا لتخطيط الصفحة</span></span>
<span class="line"><span>2. تحديد هياكل البيانات والمنطق التفاعلي</span></span>
<span class="line"><span>3. تحديد مجموعة التقنيات (مثل React + Tailwind)</span></span>
<span class="line"><span>4. قائمة نقاط الوظائف الأساسية التي يجب تنفيذها</span></span></code></pre></div><p>عادةً ما سُولد AI prompt منظمًا مشابهًا لما يلي: <img src="`+b+'" alt=""></p><p>يمكنك تعديل هذا prompt قليلاً ثم إرساله إلى AI IDE لتوليد الكود.</p><h3 id="_2-2-الخطوة-الثانية-دع-ai-ide-يولد-الكود-مباشرة" tabindex="-1">2.2 الخطوة الثانية: دع AI IDE يولد الكود مباشرة <a class="header-anchor" href="#_2-2-الخطوة-الثانية-دع-ai-ide-يولد-الكود-مباشرة" aria-label="Permalink to “2.2 الخطوة الثانية: دع AI IDE يولد الكود مباشرة”">​</a></h3><h4 id="_2-2-1-التحضير-فهم-العمليات-الأساسية-لـ-ai-ide" tabindex="-1">2.2.1 التحضير: فهم العمليات الأساسية لـ AI IDE <a class="header-anchor" href="#_2-2-1-التحضير-فهم-العمليات-الأساسية-لـ-ai-ide" aria-label="Permalink to “2.2.1 التحضير: فهم العمليات الأساسية لـ AI IDE”">​</a></h4><p>إذا لم تكن معتادًا بعد على الاستخدام الأساسي لـ AI IDE (مثل Cursor و Trae و Windsurf)، نوصي بأولًا قراءة <a href="/easy-vibe-ja-learning-map/zh-cn/appendix/2-development-tools/ide-basics/">البرنامج التعليمي الأساسي لـ IDE</a> في الملحق، لمعرفة كيفية:</p><ul><li>إنشاء مشروع جديد</li><li>التحدث مع AI Agent</li><li>فهم عملية توليد الكود من قبل AI</li></ul><h4 id="_2-2-2-ابدأ-توليد-الكود" tabindex="-1">2.2.2 ابدأ توليد الكود <a class="header-anchor" href="#_2-2-2-ابدأ-توليد-الكود" aria-label="Permalink to “2.2.2 ابدأ توليد الكود”">​</a></h4><p>الآن حصلت على prompt الأولي، لنأخذ أسلوب prompt الأول كمثال، ودع AI يساعدنا في توليد الكود. أولًا أنشئ نافذة ومجلدًا مقابلًا، وافتح المجلد (أنشئ مشروعًا جديدًا في عنوان المجلد المفضل لديك): <img src="'+_+'" alt=""><img src="'+q+'" alt=""></p><p>في الشريط الجانبي اختر نموذجًا تفضله (يوصى بـ gemini أو gpt أو glm أو kimi أو minimax، إلخ)، وأدخل prompt الذي حصلت عليه في الخطوة الأولى: <img src="'+I+'" alt=""></p><p>بعد النقر على توليد، سنرى الجزء المألوف، سيقوم AI بناءً على prompt بتخطيط هيكل المشروع والملفات الضرورية وإعطاء المحتوى الأولي لكل ملف.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ ملاحظة خاصة: قد يتوقف AI وينتظر تأكيدك</p><p>أثناء عملية التوليد، غالبًا ما <strong>يتوقف AI Agent لينتظر إدخالك أو تأكيدك</strong>، مثل:</p><ul><li>السؤال عما إذا كنت ستستمر في الخطوة التالية</li><li>طلب منك الضغط على Enter لتأكيد عملية معينة</li><li>السؤال عن اختيارك في تفصيل تقني معين</li></ul><p><strong>إذا رأيت أن AI لا يتحرك، تحقق أولًا من واجهة المحادثة، لمعرفة ما إذا كان ينتظر ردك.</strong> العديد من المبتدئين يعتقدون أن AI يفكر، لكنه في الواقع توقف منذ فترة وينتظرك. رد بفاعلية أو اضغط Enter، وسيستمر AI في العمل.</p></div><p>في هذه اللحظة لا تنسَ الضغط على Enter لتأكيد المعلومات (وإلا ستعلق في الانتظار، بعض AI IDE لا تواجه هذه المشكلة): <img src="'+k+'" alt=""></p><p>إذا واجهت السيناريو التالي، هذا يعني أنه تم تشغيل خدمة محليًا، تحتاج إلى النقر على تخطي، وإلا ستعلق على هذه الواجهة (إذا لم يظهر شيء بعد اكتمال توليد الكود، تحتاج إلى قول بنشاط &quot;ساعدني في تشغيل هذا المشروع&quot;): <img src="'+A+'" alt=""></p><div class="info custom-block"><p class="custom-block-title">💡 شرح السيناريو</p><p><strong>شرح السيناريو</strong>: أنشأت مشروع React + TypeScript باستخدام <code>npm create vite@latest</code> (easy-vibe-web)، وبعد الإنشاء سيقوم الكمبيوتر تلقائيًا بتشغيل هذه صفحة الويب &quot;لتسهيل رؤية التأثير فورًا&quot;.</p><p><strong>الخدمة المحلية</strong>: يمكن فهمها على أن الكمبيوتر فتح نافذة عرض صفحة ويب مؤقتة، تعمل فقط على جهازك، لا يمكن للآخرين الوصول إليها.</p><p><strong>localhost (العنوان المحلي)</strong>: <code>localhost</code> يعني &quot;هذا الكمبيوتر نفسه&quot;، عندما يتصفحه المتصفح، فإنه في الواقع يزور صفحة الويب التي تعمل على جهازك.</p><p><strong>المنفذ</strong>: يمكن فهم المنفذ على أنه رقم لتمييز خدمات الويب المختلفة التي تعمل على نفس الكمبيوتر، هذا المشروع يستخدم 5174.</p><p><strong>رابط الوصول <code>http://localhost:5174/</code></strong>: هذا العنوان يعني &quot;زور صفحة الويب رقم 5174 على هذا الكمبيوتر&quot;، افتحها في المتصفح لرؤية التأثير.</p><p><strong>شرح هذا السيناريو</strong>: النظام أراد استخدام 5173 في الأصل، لكن هذا الرقم كان مشغولاً فتم التبديل تلقائيًا إلى 5174، هذا أمر طبيعي.</p><p><strong>دليل التشغيل</strong>: افتح المتصفح، أدخل <code>http://localhost:5174/</code> في شريط العنوان واضغط Enter، لرؤية صفحة المشروع الحالية.</p></div><p>بعد التأكد من كل شيء، انتظر قليلاً حتى يعمل الذكاء الاصطناعي، يمكننا الحصول على النتيجة التالية: <img src="'+f+'" alt=""></p><p>يمكننا رؤية أن هناك بالفعل رسم وظيفي أولي، لكن واجهة الواجهة الأمامية قبيحة جدًا، في هذه اللحظة يمكننا محاولة التحدث مع AI مباشرة لتحسين عرض الواجهة: <img src="'+x+'" alt=""></p><p>بعد التحسين يمكننا الحصول على واجهة أجمل: <img src="'+v+'" alt=""></p><p>يمكنك تعديل وظائف صفحة الويب حسب احتياجاتك، ويمكنك إرفاق لقطات شاشة والسؤال بحرية، مثل: &quot;أنا لا أحتاج وظيفة الاستيراد الجماعي حاليًا، ساعدني في إلغائها&quot;، &quot;الأشياء التي يجب إدخالها على اليسار كثيرة جدًا، ساعدني في الاحتفاظ بـ xxxxx فقط&quot;. حتى يمكنك الرجوع إلى مواقع ويب ناضجة أخرى، مثل هنا يمكننا الرجوع مباشرة إلى منتج تصميم من Google كـ &quot;مرجع&quot; (يمكنك لصق لقطة شاشة لأي موقع ويب ناضج تحبه): <img src="'+y+'" alt=""></p><p>أخيرًا يمكننا الحصول على: <img src="'+C+'" alt=""></p><h3 id="_2-3-ماذا-تفعل-عند-مواجهة-أخطاء" tabindex="-1">2.3 ماذا تفعل عند مواجهة أخطاء <a class="header-anchor" href="#_2-3-ماذا-تفعل-عند-مواجهة-أخطاء" aria-label="Permalink to “2.3 ماذا تفعل عند مواجهة أخطاء”">​</a></h3><p>في الممارسة الفعلية، مواجهة الأخطاء أمر حتمي، هذا طبيعي، ولا يعني أنك أخطأت في مكان ما. لا تحتاج إلى فهم الخطأ، فقط أعطِ AI &quot;ما تراه&quot; بالكامل.</p><p>طرق المعالجة الشائعة ثلاثة فقط:</p><ul><li><p><strong>الطريقة الأولى: خطأ في الصفحة أو الطرفية</strong> عندما تصبح الصفحة حمراء أو شاشة بيضاء، أو تظهر كومة من النصوص الحمراء في الطرفية، فقط التقط صورة شاشة أو انسخ جميع معلومات الخطأ وأرسلها إلى AI، واطلب منه الإصلاح.</p></li><li><p><strong>الطريقة الثانية: الوظيفة خاطئة لكن لا يوجد خطأ</strong> مثل عدم استجابة الزر، أو عدم عرض البيانات، أو اختلال الأنماط، صف &quot;ماذا يحدث الآن + ماذا تريد في الأصل&quot; بلغة بسيطة، وأضف لقطة شاشة عند الضرورة.</p></li><li><p><strong>الطريقة الثالثة: غير متأكد مما إذا كانت هناك مشكلة</strong> يمكنك سؤال AI مباشرة: &quot;ساعدني في فحص ما إذا كانت هناك مشاكل واضحة في هذه الوظيفة، وهل يحتاج تعديل.&quot;</p></li></ul><h4 id="_2-3-1-أسئلة-شائعة-للمبتدئين" tabindex="-1">2.3.1 أسئلة شائعة للمبتدئين <a class="header-anchor" href="#_2-3-1-أسئلة-شائعة-للمبتدئين" aria-label="Permalink to “2.3.1 أسئلة شائعة للمبتدئين”">​</a></h4><ul><li><p><strong>س: لا أعرف أين توجد معلومات الخطأ؟</strong></p></li><li><p>ج: بشكل عام، انظر إلى كل &quot;النصوص الحمراء&quot;. في الطرفية أو وحدة التحكم أو الصفحة، اعثر على التلميح الأحمر، حدد الكل وانسخه إلى AI.</p></li><li><p><strong>س: ماذا أفعل إذا أصلح AI ولا يزال نفس الخطأ يظهر؟</strong></p></li><li><p>ج: هذا شائع. استمر في التقاط صورة أو نسخ أحدث معلومات الخطأ وإرسالها إليه، واطلب منه المزيد من الإصلاح بناءً على التعديل السابق.</p></li><li><p><strong>س: هل أحتاج إلى فهم خطة إصلاح AI بالكامل؟</strong></p></li><li><p>ج: لا تحتاج إلى فهم كل شيء دفعة واحدة. يمكنك التركيز على نقطة أو نقطتين في كل مرة، بمرور الوقت ستفهم المزيد والمزيد من الكود، مثلما تتراكم مفردات اللغة الإنجليزية.</p></li><li><p><strong>س: ماذا أفعل إذا تم التعديل عدة مرات ولم يتم حل المشكلة؟</strong></p></li><li><p>ج: يمكنك تجربة:</p><ul><li>استخدام وظيفة &quot;التراجع عن الإصدار&quot; في IDE، والعثور على زر التراجع في محادثة الذكاء الاصطناعي، والعودة إلى إصدار يعمل وإعادة البدء؛</li><li>تغيير النموذج أو تعديل prompt، وجعل الظاهرة ومعلومات الخطأ أكثر تحديدًا؛</li><li>حزم &quot;الكود الحالي + سجل الأخطاء + السلوك المتوقع&quot;، وأرسلها دفعة واحدة إلى AI، واطلب منه إعادة هيكلة الجزء المشكل بالكامل.</li></ul></li></ul><h2 id="_3-التوسع-من-صفحة-واحدة-إلى-تطبيق-متعدد-الصفحات" tabindex="-1">3. التوسع من صفحة واحدة إلى تطبيق متعدد الصفحات <a class="header-anchor" href="#_3-التوسع-من-صفحة-واحدة-إلى-تطبيق-متعدد-الصفحات" aria-label="Permalink to “3. التوسع من صفحة واحدة إلى تطبيق متعدد الصفحات”">​</a></h2>',45)),s("div",G,[a(r,null,{default:l(()=>[a(o,{active:2,items:[{title:"تحليل المتطلبات",description:"من الغامض إلى المحدد"},{title:"التحقق من صفحة واحدة",description:"تنفيذ الوظيفة الأساسية"},{title:"التوسع متعدد الصفحات",description:"تحسين بنية التطبيق"},{title:"التحسين والتجميل",description:"تحسين تجربة المستخدم"}]})]),_:1})]),n[11]||(n[11]=i('<p>عندما يكتمل توليد منطق الوظيفة الأساسية بشكل أساسي، يمكننا توليد باقي المحتوى. على سبيل المثال، في هذه اللحظة النقر على الإعدادات أو بعض الأزرار لا فائدة منه على الإطلاق.</p><p>يمكنك أن تطلب من AI التحقق بناءً على متطلبات prompt الأعمال، وتوليد الأجزاء غير المولدة، أو جعل AI يكمل مباشرة الصفحات غير المنفذة، ويمكنك أيضًا تحديد صفحة معينة وطلب من AI إكمالها حتى تصبح الصفحة قابلة للنقر والوظائف تعمل بشكل طبيعي: <img src="'+T+'" alt=""></p><p>بعد الانتظار قليلاً، يمكننا رؤية أن البرنامج قد أضاف عدة صفحات ووظائف تفاعلية على الأساس السابق: <img src="'+E+'" alt=""></p><p><img src="'+P+'" alt=""></p><p>في هذه اللحظة تحتاج فقط إلى النقر يدويًا على كل وظيفة وزر تهتم به، والتأكد من أن التفاعل طبيعي، وإذا كانت هناك وظائف لا تعمل، يمكنك التواصل مع AI وطلب منه المساعدة في الإصلاح.</p><h2 id="_4-اجعل-النموذج-الأولي-يبدو-احترافيًا" tabindex="-1">4. اجعل النموذج الأولي &quot;يبدو احترافيًا&quot; <a class="header-anchor" href="#_4-اجعل-النموذج-الأولي-يبدو-احترافيًا" aria-label="Permalink to “4. اجعل النموذج الأولي &quot;يبدو احترافيًا&quot;”">​</a></h2>',6)),s("div",W,[a(r,null,{default:l(()=>[a(o,{active:3,items:[{title:"تحليل المتطلبات",description:"من الغامض إلى المحدد"},{title:"التحقق من صفحة واحدة",description:"تنفيذ الوظيفة الأساسية"},{title:"التوسع متعدد الصفحات",description:"تحسين بنية التطبيق"},{title:"التحسين والتجميل",description:"تحسين تجربة المستخدم"}]})]),_:1})]),n[12]||(n[12]=i(`<p>بعد وجود بنية متعددة الصفحات، الخطوة الأخيرة هي تحويل النموذج الأولي من &quot;يعمل&quot; إلى &quot;سهل الاستخدام ومظهر احترافي&quot;. هذا يتطلب منا تجربة العملية الكاملة يدويًا (عملية المستخدم)، وجعل الأجزاء التي لا تعمل يصلحها AI، حتى نتمكن من محاكاة مستخدم جديد يمر بجميع العملية من الصفر في كل مرة نحدّث فيها، والحصول على النتائج المتوقعة.</p><p>دعنا نراجع المتطلبات الأولية:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. مساعدة فريق التشغيل في إنشاء المسودة الأولى للصور والنصوص بشكل جماعي:</span></span>
<span class="line"><span>- **المدخلات (دعم الرفع المباشر والاستيراد الجماعي للمواد):**</span></span>
<span class="line"><span>  - المعلومات الأساسية للمنتج: الاسم، الفئة، العلامة التجارية، المادة، الحجم، اللون، الفئة المستهدفة، إلخ؛</span></span>
<span class="line"><span>  - صور المنتج: صور بخلفية بيضاء / صور مشاهد بسيطة؛</span></span>
<span class="line"><span>  - كل توليد يدعم رفع لقطات شاشة لمنتجات ناجحة سابقًا أو روابط مرجعية إضافية؛</span></span>
<span class="line"><span>  - دعم الاستيراد الجماعي عبر Excel، أو الإدخال/الرفع عبر الإنترنت على الصفحة.</span></span>
<span class="line"><span>  - دعم تحديد ما إذا كان سيتم حفظ مواد المنتج في مكتبة المواد على الصفحة</span></span>
<span class="line"><span>- **المخرجات (محتوى يمكن نشره مباشرة أو نشره بعد تعديل بسيط):**</span></span>
<span class="line"><span>  - لكل منتج مسودة صورة رئيسية &quot;مقبولة تحتوي على نقاط بيع أساسية&quot;؛</span></span>
<span class="line"><span>  - عنوان &quot;ببنية معقولة يحتوي على كلمات مفتاحية أساسية&quot; + 1-2 جملة نص نقاط بيع.</span></span>
<span class="line"><span>- **التغيير المتوقع في طريقة الاستخدام:**</span></span>
<span class="line"><span>  من البدء من الصفر لكل دفعة منتجات إلى رمي مجموعة منتجات في النظام، وأخذ المسودات المولدة للفرز والتعديل الدقيق.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. تحويل المخرجات الجيدة إلى مكتبة قوالب قابلة لإعادة الاستخدام:</span></span>
<span class="line"><span>- **ما الذي يمكن حفظه؟**</span></span>
<span class="line"><span>  - أي مخرج يعتقد فريق التشغيل أنه &quot;جيد&quot; يمكن حفظه بنقرة واحدة:</span></span>
<span class="line"><span>    - يمكن أن يكون مجموعة كاملة من &quot;الصورة الرئيسية + العنوان + نقاط البيع&quot;؛</span></span>
<span class="line"><span>    - أو حفظ جزء منه فقط، مثل بنية عنوان معينة أو نص نقاط بيع.</span></span>
<span class="line"><span>- **ماذا يمكن فعله بعد الحفظ؟**</span></span>
<span class="line"><span>  - **إعادة الاستخدام:**</span></span>
<span class="line"><span>    - استخدم هذا المحفوظ، طبّق على مجموعة جديدة من معلمات المنتج، وأعد توليد مسودات الصور والنصوص؛</span></span>
<span class="line"><span>    - أو على نفس المنتج، ولّد نسخًا متعددة بناءً على هذا القالب لاختبار A/B.</span></span>
<span class="line"><span>  - **التعديل:**</span></span>
<span class="line"><span>    - تعديل نص العنوان / نص نقاط البيع مباشرة؛</span></span>
<span class="line"><span>    - إذا كان يدعم تعديل الصور، يمكن تعديل النصوص والملصقات في الصورة الرئيسية بدقة.</span></span>
<span class="line"><span>  - **الإدارة:**</span></span>
<span class="line"><span>    - إعطاء اسم للمحفوظ وإضافة علامات (مثل &quot;قالب صور حقائب رجالية&quot; &quot;بنية عنوان ترويج كبير&quot;)، ودعم التصنيف حسب المتجر، للسهولة في البحث لاحقًا.</span></span>
<span class="line"><span>- **كيف تستخدم عند النشر الجديد؟**</span></span>
<span class="line"><span>  - بعد استيراد منتجات جديدة، يمكن لفريق التشغيل الاختيار:</span></span>
<span class="line"><span>    - استخدام منطق التوليد الافتراضي للنظام، أو</span></span>
<span class="line"><span>    - تحديد &quot;استخدام قالب محفوظ معين للتوليد&quot;؛</span></span>
<span class="line"><span>  - النظام يطبق تلقائيًا بنية ونمط القالب بناءً على بيانات المنتج الجديدة، ويخرج مسودة جديدة للصورة الرئيسية + العنوان + نقاط البيع.</span></span></code></pre></div><p>إذا كنت تحتاج في كل مرة إلى إنشاء بيانات جديدة للاختبار، فهذا يستغرق وقتًا طويلاً، في هذه الحالة نستخدم عادةً طريقة تسمى &quot;بيانات الاختبار&quot;، يمكنك التواصل مع AI بالطريقة التالية، وطلب منه إنشاء مدخل لبيانات اختبار سريعة على الواجهة، لتسهيل اختبار ما إذا كانت جميع الوظائف تعمل بشكل طبيعي:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>أحتاج الآن إلى اختبار عملية المستخدم هذه، للتأكد من أنه يمكنه إكمالها بالكامل، يرجى توليد مدخل بيانات اختبار بناءً على المتطلبات أدناه، لتمكيني من النقر واختبار ما إذا كانت العملية الكاملة تعمل بشكل طبيعي بسرعة:</span></span>
<span class="line"><span>1. مساعدة فريق التشغيل في إنشاء المسودة الأولى للصور والنصوص بشكل جماعي:</span></span>
<span class="line"><span>- **المدخلات (دعم الرفع المباشر والاستيراد الجماعي للمواد):**</span></span>
<span class="line"><span>  - المعلومات الأساسية للمنتج: الاسم، الفئة، العلامة التجارية، المادة، الحجم، اللون، الفئة المستهدفة، إلخ؛</span></span>
<span class="line"><span>  - صور المنتج: صور بخلفية بيضاء / صور مشاهد بسيطة؛</span></span>
<span class="line"><span>  - كل توليد يدعم رفع لقطات شاشة لمنتجات ناجحة سابقًا أو روابط مرجعية إضافية؛</span></span>
<span class="line"><span>  - دعم الاستيراد الجماعي عبر Excel، أو الإدخال/الرفع عبر الإنترنت على الصفحة.</span></span>
<span class="line"><span>  - دعم تحديد ما إذا كان سيتم حفظ مواد المنتج في مكتبة المواد على الصفحة</span></span>
<span class="line"><span>- **المخرجات (محتوى يمكن نشره مباشرة أو نشره بعد تعديل بسيط):**</span></span>
<span class="line"><span>  - لكل منتج مسودة صورة رئيسية &quot;مقبولة تحتوي على نقاط بيع أساسية&quot;؛</span></span>
<span class="line"><span>  - عنوان &quot;ببنية معقولة يحتوي على كلمات مفتاحية أساسية&quot; + 1-2 جملة نص نقاط بيع.</span></span>
<span class="line"><span>- **التغيير المتوقع في طريقة الاستخدام:**</span></span>
<span class="line"><span>  من البدء من الصفر لكل دفعة منتجات إلى رمي مجموعة منتجات في النظام، وأخذ المسودات المولدة للفرز والتعديل الدقيق.</span></span></code></pre></div><p>سهل الحصول على النتيجة (إذا كنت تعتقد أن بيانات واحدة غير كافية، يمكنك أن تطلب من AI توليد حالات اختبار متعددة): <img src="`+D+'" alt=""></p><p>بعد النقر نحصل على النتيجة: <img src="'+S+'" alt=""></p><p>في هذه اللحظة ما نحصل عليه مباشرة هو النتيجة، وليس &quot;عملية توليد افتراضية&quot;، إذا أردنا محاكاة عملية توليد حقيقية، يمكننا التحدث مع AI مباشرة: &quot;يرجى محاكاة عملية توليد حقيقية، وإعطائي النتيجة بعد فترة من الوقت بعد النقر.&quot; <img src="'+V+'" alt=""></p><p>بعد التأكد من وظيفة التوليد، يجب أيضًا التأكد من أن وظائف مكتبة القوالب تعمل بشكل طبيعي، من بطاقة التوليد على الصفحة يمكننا أن نعرف أن وظيفة حفظ مكتبة القوالب لم تُنفذ بعد، في هذه اللحظة نحتاج إلى مزيد من المحادثة العميقة مع AI، &quot;يرجى التأكد من أن المتطلبات [الصق محتوى البند 2 أعلاه هنا] تعمل بشكل طبيعي، يمكن النقر على نتيجة لحفظ القالب المقابل، وبعد الفتح يمكن رؤية معلمات التوليد&quot;</p><p>التوليد غالبًا ليس مرة واحدة، غالبًا ما يحتاج إلى لقطات شاشة للتصحيح: <img src="'+N+'" alt=""></p><p>أخيرًا نحصل على النتيجة المتوقعة: <img src="'+R+'" alt=""></p><p>بالإضافة إلى تجربة عملية عملية لمتطلبات العملية، يمكنك أيضًا أن تطلب من AI مساعدتك في فحص المتطلبات مباشرة، مثل:</p><ul><li>&quot;يرجى مقارنة متطلباتي الأولية، والتحقق مما إذا كان التطبيق الحالي يغطي جميع الوظائف الأساسية.&quot;</li><li>&quot;ساعدني في عمل قائمة وظائف، وحدد ما تم إنجازه وما لم يُنفذ بعد أو تجربته غير كافية.&quot;</li></ul><p>عادةً ما سيُخرج AI قائمة تحقق، يمكنك التفكير بناءً على النتائج فيما إذا كنت بحاجة إلى الاستمرار في التحسين، وبعد التعديل المتكرر يمكنك الحصول على نتيجة نموذج أولي أكثر اكتمالاً.</p><h2 id="_5-📚-الواجب-أعد-إنشاء-منصة-التجارة-الإلكترونية-الخاصة-بك" tabindex="-1">5. 📚 الواجب: أعد إنشاء منصة التجارة الإلكترونية الخاصة بك <a class="header-anchor" href="#_5-📚-الواجب-أعد-إنشاء-منصة-التجارة-الإلكترونية-الخاصة-بك" aria-label="Permalink to “5. 📚 الواجب: أعد إنشاء منصة التجارة الإلكترونية الخاصة بك”">​</a></h2>',15)),a(e,{shadow:"hover",style:{margin:"20px 0","border-radius":"12px"}},{header:l(()=>[...n[2]||(n[2]=[s("div",{style:{"font-weight":"bold","font-size":"16px"}},"🚀 مهمة التحدي: أعد إنشاء منصة مواد التجارة الإلكترونية",-1)])]),default:l(()=>[n[3]||(n[3]=s("p",null," بالرجوع إلى prompt ومحتوى هذا الدرس، أكمل دورة كاملة: ",-1)),n[4]||(n[4]=s("ul",null,[s("li",null,[s("strong",null,"ممارسة الدورة الكاملة"),s("ul",null,[s("li",null,"تنظيم الأعمال وتوليد prompt → توليد نموذج أولي لصفحة واحدة → توليد نموذج أولي متعدد الصفحات")])]),s("li",null,[s("strong",null,"مشاركة النتائج"),s("ul",null,[s("li",null,"التقط لقطة شاشة لبرنامجك وشاركها مع الجميع")])]),s("li",null,[s("strong",null,"سؤال تفكيري"),s("ul",null,[s("li",null,'اترك مجالاً للقسم التالي "ربط نموذج اللغة الكبير (LLM) وقدرات إنشاء الصور من النص"، فكر مسبقًا: كيف يمكنك تضمين قدرات مثل "AI لكتابة النصوص / إنشاء صور مرافقة / إنشاء نصوص برمجية" في منصتك؟')])])],-1))]),_:1}),n[13]||(n[13]=s("h2",{id:"الخطوة-التالية",tabindex:"-1"},[t("الخطوة التالية "),s("a",{class:"header-anchor",href:"#الخطوة-التالية","aria-label":"Permalink to “الخطوة التالية”"},"​")],-1)),n[14]||(n[14]=s("p",null,"في القسم التالي، سنضيف قدرات AI محددة (نص إلى نص، صورة إلى نص، نص إلى صورة) إلى منصة إنتاج المحتوى هذه، مثل:",-1)),n[15]||(n[15]=s("ul",null,[s("li",null,"التوليد التلقائي لمسودة نصية وعناوين بديلة متعددة لمهمة محتوى معينة"),s("li",null,"التوليد التلقائي لمسودة صور مرافقة بناءً على وصف المهمة (نص إلى صورة)"),s("li",null,"التصنيف والملخص التلقائي لمهام المحتوى السابقة، لمساعدتك في تخطيط مواضيع النشاط التالي")],-1)),a(d,{title:"متابعة التعلم",description:"يوصى بالمتابعة بترتيب 'ربط قدرات AI → دورة مشروع كاملة → هندسة التصميم'.",items:w(u)},null,8,["items"])])}}});export{K as __pageData,Q as default};
